### The Smart Badge Reader Sketch
Let's write a complete Arduino sketch to initialize the RC522 reader module over SPI and print the hexadecimal Unique Identifier (UID) of any tapped card or keychain tag to the Serial Monitor!

```cpp
#include <SPI.h>
#include <MFRC522.h>

// Pin definitions for RC522
const int SS_PIN  = 10; // Chip Select (labeled SDA on module)
const int RST_PIN = 9;  // Hardware Reset pin

MFRC522 rfid(SS_PIN, RST_PIN); // Create MFRC522 instance

void setup() {
  Serial.begin(9600);
  while (!Serial);

  SPI.begin();       // 1. Initialize SPI bus (Pins 11, 12, 13)
  rfid.PCD_Init();   // 2. Initialize MFRC522 silicon over SPI

  Serial.println("====================================");
  Serial.println("MONSTER ACCESS CONTROL TERMINAL READY");
  Serial.println("Tap your RFID card or key fob...");
  Serial.println("====================================");
}

void loop() {
  // 1. Look for new cards in the 13.56 MHz field
  if (!rfid.PICC_IsNewCardPresent()) {
    return;
  }

  // 2. Interrogate the card and read its serial number
  if (!rfid.PICC_ReadCardSerial()) {
    return;
  }

  // 3. Print the Unique Identifier (UID)
  Serial.print("SUCCESS: Card Detected! UID (HEX): ");
  for (byte i = 0; i < rfid.uid.size; i++) {
    if (rfid.uid.uidByte[i] < 0x10) {
      Serial.print(" 0");
    } else {
      Serial.print(" ");
    }
    Serial.print(rfid.uid.uidByte[i], HEX);
  }
  Serial.println();

  // 4. Halt the card so it doesn't continuously trigger
  rfid.PICC_HaltA();
  rfid.PCD_StopCrypto1();
  delay(500);
}
```

### Code Breakdown:
- `rfid.PCD_Init()`: Sends commands over hardware SPI to configure the RC522's internal antenna gain, timer registers, and modulation depth.
- `rfid.PICC_IsNewCardPresent()`: Queries whether a resonant 13.56 MHz tag is currently drawing energy from the antenna field.
- `rfid.uid.uidByte[i]`: Accesses each byte of the card's burned-in hardware serial number (typically a 4-byte string such as `DE AD BE EF`).
